const q = String($('Tool Input').first().json.query || '').toLowerCase();
const words = q.split(/[^\p{L}\p{N}]+/u).filter(w => w.length > 2);
const rows = $input.all().map(i => i.json).filter(r => r.quote);
function score(r) {
  const hay = (r.quote + ' ' + r.source_title + ' ' + (r.note || '')).toLowerCase();
  return words.filter(w => hay.includes(w)).length;
}
let picked = rows;
if (words.length) {
  picked = rows.map(r => ({ r, s: score(r) })).filter(x => x.s > 0).sort((a, b) => b.s - a.s).map(x => x.r);
}
const entries = picked.slice(0, 40).map(r => ({ ledger_id: r.id, quote: r.quote, page: r.page || 'not recorded', source: r.source_title, authors: r.authors, year: r.year, doi: r.doi }));
return [{ json: { total_in_ledger: rows.length, returned: entries.length, entries } }];

const j = $input.first().json;
const q = String(j.query || '').trim();
const base = 'https://api.openalex.org/works';
const select = 'select=doi,title,publication_year,authorships,abstract_inverted_index,primary_location';
const m = q.match(/10[.][0-9]{4,9}[/][^ ]+/);
let url;
if (j.action === 'verify' && m) {
  const doi = m[0].replace(/[.,;)]+$/, '').toLowerCase();
  url = base + '?filter=doi:' + encodeURIComponent(doi) + '&' + select;
} else if (j.action === 'verify') {
  url = base + '?filter=title.search:' + encodeURIComponent(q.replace(/[,:|]/g, ' ')) + '&per_page=3&' + select;
} else {
  url = base + '?search=' + encodeURIComponent(q) + '&per_page=5&' + select;
}
return [{ json: { action: j.action, query: q, is_doi: !!m, url } }];

const req = $('Build Request').first().json;
const res = $input.first().json;
if (res.error || !Array.isArray(res.results)) {
  return [{ json: { ok: false, message: 'The paper database could not be reached. Tell the user. Do not guess.' } }];
}
function abstractOf(idx) {
  if (!idx) { return 'no abstract available'; }
  const pos = [];
  for (const [word, places] of Object.entries(idx)) { for (const p of places) { pos[p] = word; } }
  return pos.filter(Boolean).join(' ').slice(0, 500);
}
function norm(s) { return String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ''); }
const works = res.results.map(w => ({
  title: w.title,
  authors: (w.authorships || []).slice(0, 3).map(a => a.author.display_name).join(', '),
  year: w.publication_year,
  doi: String(w.doi || '').replace('https://doi.org/', ''),
  venue: w.primary_location?.source?.display_name || '',
  abstract: abstractOf(w.abstract_inverted_index)
}));
if (req.action === 'verify') {
  const verified = req.is_doi ? works.length > 0 : works.some(w => norm(w.title) === norm(req.query));
  const records = works.slice(0, 3).map(w => ({ title: w.title, authors: w.authors, year: w.year, doi: w.doi, venue: w.venue }));
  return [{ json: { ok: true, verified, searched_for: req.query, records } }];
}
return [{ json: { ok: true, results: works } }];
